-- secours-intrusion-domicile-occupants-presents — Ils se sont enfermés dans la salle de bain et chuchotent au téléphone
SELECT public.fn_cp_import_case('secours-intrusion-domicile-occupants-presents', '{"slug": "secours-intrusion-domicile-occupants-presents", "title": "Ils se sont enfermés dans la salle de bain et chuchotent au téléphone", "theme_slug": "police-secours", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 1 h 30. Vous êtes engagés au domicile d''une famille suite à un appel au 17 : la mère, réfugiée avec ses deux enfants dans la salle de bain fermée à clé, chuchote qu''un individu inconnu s''est introduit dans le pavillon par une fenêtre du rez-de-chaussée il y a quelques minutes et qu''elle entend encore du bruit au rez-de-chaussée.\n\nElle reste en ligne avec vous à voix très basse, terrifiée, incapable de dire avec certitude si l''individu est toujours dans la maison ou s''il est reparti après avoir fouillé certaines pièces. Son mari est absent, en déplacement professionnel. Elle vous supplie de ne pas raccrocher.\n\nÀ votre arrivée avec votre collègue, la maison paraît silencieuse depuis l''extérieur, aucune lumière visible, la porte d''entrée semblant fermée normalement.", "questions": [{"position": 1, "max_points": 5, "label": "Comment exploitez-vous le contact téléphonique maintenu avec la mère pendant votre approche de la maison ?", "hint": "Ce contact vocal en direct est une ressource précieuse à ne pas interrompre prématurément.", "perfect": "Je maintiens ce contact téléphonique aussi longtemps que possible, cette ligne ouverte constituant une source d''information en temps réel sur l''évolution de la situation à l''intérieur, bien plus précieuse qu''une reconstitution après coup.\n\nJe demande à la mère de continuer à me signaler tout bruit qu''elle perçoit depuis son abri, sans lui demander de sortir de la salle de bain ni de prendre le moindre risque pour m''informer davantage, sa sécurité restant prioritaire sur la qualité de l''information.\n\nJe guide mon approche de la maison en tenant compte de ce qu''elle me rapporte en direct, ce qui me permet d''orienter mes collègues vers les zones les plus pertinentes plutôt que de procéder à une exploration aveugle et non coordonnée.\n\nJe la rassure régulièrement par quelques mots brefs pour qu''elle sache que nous sommes sur place et progressons, sans pour autant l''obliger à parler davantage que ce que sa sécurité immédiate permet.", "points": [{"position": 1, "label": "Maintenir le contact téléphonique aussi longtemps que possible", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : source d''information en temps réel précieuse pour guider l''approche.", "groups": [{"position": 1, "keywords": ["maintenir le contact", "temps réel", "source précieuse"]}]}, {"position": 2, "label": "Ne jamais lui demander de sortir ou de prendre un risque pour informer davantage", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Sa sécurité prime sur la qualité de l''information recueillie.", "groups": [{"position": 1, "keywords": ["ne pas lui demander de sortir", "sécurité prioritaire", "pas de risque"]}]}, {"position": 3, "label": "Guider l''approche en tenant compte des informations en direct", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Orienter les collègues plutôt qu''une exploration aveugle.", "groups": [{"position": 1, "keywords": ["guider l''approche", "orienter les collègues", "pas aveugle"]}]}, {"position": 4, "label": "La rassurer brièvement sans exiger qu''elle parle plus que nécessaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Communication minimale respectant sa sécurité immédiate.", "groups": [{"position": 1, "keywords": ["rassurer brièvement", "sans exiger davantage", "sécurité immédiate"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment organisez-vous concrètement l''entrée et la progression dans la maison avec votre collègue ?", "hint": "L''incertitude sur la présence de l''intrus impose une méthode différente d''une entrée dans un logement vide confirmé.", "perfect": "Je procède à une entrée méthodique et coordonnée avec mon collègue, en considérant que l''intrus peut toujours être présent tant que rien ne permet formellement d''écarter cette hypothèse.\n\nJe répartis les rôles clairement avant d''entrer, l''un progressant pendant que l''autre couvre, plutôt que d''avancer de manière désorganisée ou de nous séparer sans communication.\n\nJe privilégie une progression pièce par pièce en sécurisant chaque espace avant de passer au suivant, sans se précipiter vers la salle de bain où se trouvent la mère et les enfants avant d''avoir sécurisé le chemin pour y parvenir.\n\nJe reste attentif aux indices matériels d''une éventuelle fuite de l''intrus, comme une fenêtre ouverte ou des traces de passage, qui pourraient m''aider à évaluer si la menace est toujours présente ou déjà écartée.", "points": [{"position": 1, "label": "Considérer que l''intrus peut toujours être présent tant que rien ne l''écarte", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Prudence maintenue malgré l''apparence de calme extérieur.", "groups": [{"position": 1, "keywords": ["intrus peut être présent", "tant que rien n''écarte", "prudence maintenue"]}]}, {"position": 2, "label": "Répartir clairement les rôles avant d''entrer avec le collègue", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Progression coordonnée plutôt que désorganisée ou séparée.", "groups": [{"position": 1, "keywords": ["répartir les rôles", "coordonné", "pas séparé"]}]}, {"position": 3, "label": "Progresser pièce par pièce en sécurisant avant d''avancer", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ne pas se précipiter vers la salle de bain sans sécuriser le chemin.", "groups": [{"position": 1, "keywords": ["pièce par pièce", "sécuriser avant d''avancer", "ne pas se précipiter"]}]}, {"position": 4, "label": "Rester attentif aux indices matériels d''une fuite de l''intrus", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Fenêtre ouverte ou traces de passage pour évaluer la menace.", "groups": [{"position": 1, "keywords": ["indices matériels", "fenêtre ouverte", "évaluer la menace"]}]}]}, {"position": 3, "max_points": 5, "label": "Une fois la maison sécurisée sans trouver l''intrus, comment accompagnez-vous la mère et ses enfants sortis de la salle de bain ?", "hint": "L''absence de découverte de l''intrus ne signifie pas que la peur vécue était disproportionnée.", "perfect": "Je reconnais explicitement la légitimité de sa peur et de sa réaction, sans lui laisser penser que l''absence de découverte de l''intrus signifierait qu''elle a exagéré ou mal évalué la situation.\n\nJe recueille sa description des faits et des bruits entendus avec attention, ces éléments restant précieux pour la suite de l''enquête même si l''auteur n''a pas été retrouvé sur place.\n\nJe m''assure que les enfants, qui ont vécu cette peur intense à ses côtés, bénéficient également d''une attention et d''un réconfort adaptés à leur âge, sans les considérer comme de simples accompagnants passifs de leur mère.\n\nJe reste présente le temps nécessaire pour qu''elle se sente suffisamment en sécurité avant mon départ, en lui proposant éventuellement de faire vérifier les points d''entrée du logement pour la rassurer sur la suite de la nuit.", "points": [{"position": 1, "label": "Reconnaître la légitimité de sa peur sans découverte de l''intrus", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "L''absence de découverte ne signifie pas une réaction disproportionnée.", "groups": [{"position": 1, "keywords": ["légitimité de la peur", "pas disproportionné", "sans découverte"]}]}, {"position": 2, "label": "Recueillir sa description avec attention malgré l''absence d''interpellation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éléments précieux pour la suite de l''enquête.", "groups": [{"position": 1, "keywords": ["recueillir la description", "précieux pour l''enquête", "malgré l''absence"]}]}, {"position": 3, "label": "S''assurer que les enfants bénéficient aussi d''attention et de réconfort", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ne pas les traiter comme de simples accompagnants passifs.", "groups": [{"position": 1, "keywords": ["attention aux enfants", "réconfort adapté", "pas passifs"]}]}, {"position": 4, "label": "Rester présente le temps nécessaire et vérifier les points d''entrée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Rassurer sur la suite de la nuit avant de partir.", "groups": [{"position": 1, "keywords": ["rester présente", "vérifier les points d''entrée", "rassurer pour la nuit"]}]}]}]}'::jsonb);

-- secours-personne-menacant-de-se-blesser-commissariat — Il sort une lame et la pose contre son propre bras
SELECT public.fn_cp_import_case('secours-personne-menacant-de-se-blesser-commissariat', '{"slug": "secours-personne-menacant-de-se-blesser-commissariat", "title": "Il sort une lame et la pose contre son propre bras", "theme_slug": "police-secours", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 15 heures. Un homme d''une trentaine d''années, déjà venu plus tôt dans la journée pour une démarche administrative refusée, revient dans le hall du commissariat, visiblement en grande détresse. Sans prévenir, il sort un petit couteau de sa poche et le pose contre son propre avant-bras, menaçant de se couper si on ne le laisse pas « en finir ».\n\nPlusieurs usagers se trouvent encore dans le hall, dont une famille avec un jeune enfant, à quelques mètres de la scène. L''homme ne menace personne d''autre que lui-même, reste immobile, et répète entre deux sanglots qu''il « n''en peut plus » sans donner davantage de détails sur sa situation.\n\nVous êtes deux agents présents dans le hall à cet instant, sans effectif spécialisé immédiatement disponible sur place.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre toute première action face à cette scène d''auto-agression menacée dans un lieu recevant du public ?", "hint": "La présence de tiers, notamment un enfant, dans ce lieu public change la donne par rapport à une situation similaire en milieu isolé.", "perfect": "Ma toute première action est de faire évacuer discrètement mais rapidement les usagers présents dans le hall, en particulier la famille avec l''enfant, ce public n''ayant aucune raison d''assister à cette scène et sa présence pouvant également ajouter une pression sur l''homme en détresse.\n\nJe ne tente à aucun moment de m''approcher physiquement de lui ou de le désarmer par la force dans l''immédiat, un tel geste précipité pouvant au contraire précipiter le passage à l''acte qu''il menace de commettre.\n\nJe sollicite sans délai l''appui de collègues supplémentaires ou de moyens plus adaptés à ce type de situation, deux agents seuls dans le hall n''étant pas nécessairement suffisants pour gérer sereinement cette crise.\n\nJe maintiens une distance respectueuse tout en restant visible et présent, ce qui évite qu''il se sente totalement seul sans pour autant le brusquer par une proximité physique intrusive.", "points": [{"position": 1, "label": "Faire évacuer discrètement le public, en particulier l''enfant", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : évacuer le public avant tout dialogue, sans le brusquer.", "groups": [{"position": 1, "keywords": ["évacuer le public", "en particulier l''enfant", "discrètement"]}]}, {"position": 2, "label": "Ne pas tenter de le désarmer par la force dans l''immédiat", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Un geste précipité pourrait précipiter le passage à l''acte.", "groups": [{"position": 1, "keywords": ["ne pas désarmer par la force", "geste précipité", "précipiter le passage à l''acte"]}]}, {"position": 3, "label": "Solliciter sans délai des renforts ou moyens adaptés", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Deux agents seuls ne sont pas nécessairement suffisants.", "groups": [{"position": 1, "keywords": ["solliciter des renforts", "moyens adaptés", "pas suffisants seuls"]}]}, {"position": 4, "label": "Maintenir une distance respectueuse tout en restant visible", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Éviter qu''il se sente seul sans le brusquer par une proximité intrusive.", "groups": [{"position": 1, "keywords": ["distance respectueuse", "rester visible", "sans proximité intrusive"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment engagez-vous le dialogue avec lui en attendant l''appui nécessaire ?", "hint": "Un homme qui revient spécifiquement au commissariat après un refus administratif cherche peut-être avant tout à être entendu.", "perfect": "J''engage un dialogue calme en reconnaissant sa détresse sans la minimiser, en évitant de me focaliser exclusivement sur le couteau qu''il tient, ce qui pourrait renforcer son sentiment de n''être vu qu''à travers cet objet.\n\nJe l''interroge doucement sur ce qui a précédé ce moment, notamment le refus administratif du matin qui semble être un élément déclencheur, sans pour autant le presser de tout expliquer immédiatement.\n\nJe ne lui promets rien que je ne puisse tenir concernant sa démarche administrative refusée, ce qui serait contre-productif s''il découvrait rapidement que cette promesse ne pouvait être satisfaite, mais je peux lui assurer qu''on va l''écouter avec attention.\n\nJe reste attentif à tout signe d''apaisement ou au contraire d''aggravation dans son discours et son comportement, pour adapter ma communication en continu jusqu''à l''arrivée de renforts mieux formés pour poursuivre cette gestion de crise.", "points": [{"position": 1, "label": "Engager un dialogue calme en reconnaissant sa détresse sans se focaliser sur le couteau", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Éviter qu''il se sente réduit à l''objet qu''il tient.", "groups": [{"position": 1, "keywords": ["dialogue calme", "reconnaître la détresse", "pas focalisé sur l''objet"]}]}, {"position": 2, "label": "L''interroger doucement sur l''élément déclencheur sans le presser", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Le refus administratif du matin semble être un facteur important.", "groups": [{"position": 1, "keywords": ["interroger doucement", "élément déclencheur", "sans presser"]}]}, {"position": 3, "label": "Ne rien promettre qui ne pourrait être tenu concernant sa démarche", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Une fausse promesse serait contre-productive si découverte rapidement.", "groups": [{"position": 1, "keywords": ["ne rien promettre", "pas de fausse promesse", "contre-productif"]}]}, {"position": 4, "label": "Rester attentif aux signes d''évolution pour adapter la communication", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Adaptation continue jusqu''à l''arrivée de renforts spécialisés.", "groups": [{"position": 1, "keywords": ["signes d''évolution", "adapter en continu", "renforts spécialisés"]}]}]}, {"position": 3, "max_points": 5, "label": "Il finit par poser le couteau et accepte l''aide proposée. Comment gérez-vous la suite immédiate ?", "hint": "Le moment où la crise semble résolue reste sensible et appelle une suite adaptée, pas un simple retour à la routine.", "perfect": "Je récupère le couteau avec précaution une fois qu''il l''a effectivement posé et qu''il ne représente plus un risque immédiat, sans geste brusque qui pourrait le raviver dans son geste.\n\nJe m''assure qu''une prise en charge médicale et psychologique adaptée soit engagée sans délai, cette crise ne se résolvant pas simplement parce que l''objet dangereux a été écarté.\n\nJe ne le traite pas comme un simple perturbateur qu''il faudrait maintenant sanctionner administrativement pour cet épisode, en gardant à l''esprit la détresse réelle qui l''a conduit à ce geste.\n\nJe rends compte avec précision de l''ensemble du déroulement de cet incident, ce qui pourra utilement alimenter une réflexion sur la gestion de ce type de situation dans les locaux recevant du public.", "points": [{"position": 1, "label": "Récupérer le couteau avec précaution sans geste brusque", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter de raviver le geste par une action trop rapide.", "groups": [{"position": 1, "keywords": ["récupérer avec précaution", "sans geste brusque", "ne pas raviver"]}]}, {"position": 2, "label": "S''assurer d''une prise en charge médicale et psychologique sans délai", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "La crise n''est pas résolue par le seul retrait de l''objet dangereux.", "groups": [{"position": 1, "keywords": ["prise en charge médicale", "psychologique", "sans délai"]}]}, {"position": 3, "label": "Ne pas le traiter comme un simple perturbateur à sanctionner", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Garder à l''esprit la détresse réelle ayant conduit à ce geste.", "groups": [{"position": 1, "keywords": ["pas un perturbateur", "détresse réelle", "pas de sanction"]}]}, {"position": 4, "label": "Rendre compte précisément pour alimenter la réflexion du service", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Utile pour la gestion future de ce type de situation en accueil du public.", "groups": [{"position": 1, "keywords": ["rendre compte", "réflexion du service", "gestion future"]}]}]}]}'::jsonb);

-- secours-accident-trottinette-pieton — Le conducteur veut repartir, la victime est assise par terre
SELECT public.fn_cp_import_case('secours-accident-trottinette-pieton', '{"slug": "secours-accident-trottinette-pieton", "title": "Le conducteur veut repartir, la victime est assise par terre", "theme_slug": "police-secours", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 18 h 45. Vous êtes engagés sur une voie piétonne où un conducteur de trottinette électrique a percuté une passante en la doublant à vive allure. La victime, une femme d''une cinquantaine d''années, est assise par terre, se tenant le poignet, et minimise en répétant que « ce n''est rien » malgré une douleur visible à chaque mouvement.\n\nLe conducteur de la trottinette, un jeune homme, reste debout à quelques mètres, engin à la main, expliquant qu''il est « pressé » et demandant s''il peut repartir puisque la dame « dit que ça va ». Il ne semble pas connaître précisément les règles applicables à la circulation de son engin sur cette voie piétonne.\n\nAucun autre témoin direct de la collision ne s''est arrêté, la scène s''étant déroulée rapidement dans un flux de passants pressés à cette heure.", "questions": [{"position": 1, "max_points": 5, "label": "Laissez-vous le conducteur repartir sur la seule affirmation de la victime que « ça va » ?", "hint": "La minimisation de la victime et l''empressement de l''auteur ne doivent pas se substituer à une évaluation rigoureuse.", "perfect": "Je ne laisse pas le conducteur repartir sur la seule base de cette affirmation, la victime pouvant minimiser sa douleur par gêne ou par volonté de ne pas causer de complications, sans que cela reflète nécessairement la réalité de son état.\n\nJe retiens l''identité complète du conducteur avant toute chose, cette étape étant indispensable indépendamment de la suite donnée à l''incident, pour permettre toute démarche ultérieure de la victime si nécessaire.\n\nJe recueille également les circonstances précises de la collision auprès du conducteur, notamment sa vitesse et la manière dont il a doublé la victime, ces éléments étant utiles pour qualifier correctement les responsabilités.\n\nJe ne me laisse pas influencer par son empressement à repartir, qui ne constitue en rien une raison de bâcler les vérifications nécessaires à la bonne gestion de cet accident.", "points": [{"position": 1, "label": "Ne pas laisser repartir le conducteur sur la seule affirmation de la victime", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : la minimisation de la victime ne dispense pas de la rigueur.", "groups": [{"position": 1, "keywords": ["ne pas laisser repartir", "minimisation de la victime", "rigueur nécessaire"]}]}, {"position": 2, "label": "Retenir l''identité complète du conducteur avant toute chose", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Indispensable pour toute démarche ultérieure de la victime.", "groups": [{"position": 1, "keywords": ["retenir l''identité", "avant toute chose", "démarche ultérieure"]}]}, {"position": 3, "label": "Recueillir les circonstances précises de la collision", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vitesse et manière de doubler, utiles pour qualifier les responsabilités.", "groups": [{"position": 1, "keywords": ["circonstances précises", "vitesse", "qualifier les responsabilités"]}]}, {"position": 4, "label": "Ne pas se laisser influencer par l''empressement du conducteur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Aucune raison de bâcler les vérifications nécessaires.", "groups": [{"position": 1, "keywords": ["ne pas se laisser influencer", "empressement", "ne pas bâcler"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous la minimisation de la victime concernant sa propre douleur au poignet ?", "hint": "Insister sur une évaluation médicale n''est pas contradictoire avec le respect de son autonomie.", "perfect": "J''insiste avec tact pour qu''elle accepte une évaluation médicale, en lui expliquant qu''une douleur au poignet après un choc peut masquer une fracture qui n''est pas toujours immédiatement évidente sans examen approprié.\n\nJe ne la force pas si elle refuse catégoriquement après avoir été correctement informée, son autonomie de décision restant respectée, mais je m''assure qu''elle comprend bien les risques d''un refus dans ce contexte précis.\n\nJe reste attentive aux signes objectifs de sa blessure, comme un gonflement ou une déformation visible, qui pourraient renforcer la nécessité d''insister davantage sur cette évaluation médicale.\n\nJe consigne son état et sa réaction dans mon compte rendu, ce qui pourra être utile si elle décidait ultérieurement de consulter un médecin après avoir constaté une aggravation de sa douleur.", "points": [{"position": 1, "label": "Insister avec tact pour une évaluation médicale", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Une douleur au poignet peut masquer une fracture non évidente.", "groups": [{"position": 1, "keywords": ["insister avec tact", "évaluation médicale", "fracture possible"]}]}, {"position": 2, "label": "Ne pas la forcer si elle refuse après une information correcte", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Respecter son autonomie tout en s''assurant qu''elle comprend les risques.", "groups": [{"position": 1, "keywords": ["ne pas forcer", "autonomie respectée", "comprendre les risques"]}]}, {"position": 3, "label": "Rester attentive aux signes objectifs de blessure", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Gonflement ou déformation renforçant la nécessité d''insister.", "groups": [{"position": 1, "keywords": ["signes objectifs", "gonflement", "déformation visible"]}]}, {"position": 4, "label": "Consigner son état et sa réaction dans le compte rendu", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Utile en cas de consultation ultérieure après aggravation.", "groups": [{"position": 1, "keywords": ["consigner l''état", "utile ultérieurement", "aggravation possible"]}]}]}, {"position": 3, "max_points": 5, "label": "Le jeune conducteur ne connaît manifestement pas les règles applicables à son engin sur cette voie. Comment traitez-vous cet aspect ?", "hint": "L''ignorance des règles n''excuse pas l''infraction mais mérite d''être traitée avec pédagogie autant qu''avec fermeté.", "perfect": "Je lui explique clairement les règles applicables à la circulation des engins de déplacement personnel sur ce type de voie, son ignorance apparente ne constituant pas une excuse mais méritant d''être corrigée pour l''avenir.\n\nJe ne me contente pas d''une explication orale informelle si les faits le justifient, en appliquant la réponse procédurale appropriée à la gravité de l''infraction constatée et à ses conséquences pour la victime.\n\nJe reste pédagogue dans ma manière de m''adresser à lui, sans céder à un ton moralisateur excessif, ce qui serait contre-productif pour l''assimilation réelle des règles qu''il ignore visiblement.\n\nJe consigne précisément les circonstances de l''infraction constatée, ce qui pourra être utile pour la suite de la procédure concernant à la fois la victime et la qualification des faits reprochés au conducteur.", "points": [{"position": 1, "label": "Expliquer clairement les règles applicables sans excuser l''ignorance", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "L''ignorance ne constitue pas une excuse mais mérite correction pédagogique.", "groups": [{"position": 1, "keywords": ["expliquer les règles", "ignorance pas une excuse", "pédagogie"]}]}, {"position": 2, "label": "Appliquer la réponse procédurale appropriée à la gravité", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ne pas se contenter d''une explication informelle si les faits le justifient.", "groups": [{"position": 1, "keywords": ["réponse procédurale", "gravité constatée", "pas seulement informel"]}]}, {"position": 3, "label": "Rester pédagogue sans ton moralisateur excessif", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter un ton contre-productif pour l''assimilation des règles.", "groups": [{"position": 1, "keywords": ["pédagogue", "sans moraliser", "assimilation des règles"]}]}, {"position": 4, "label": "Consigner précisément les circonstances de l''infraction", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Utile pour la suite de la procédure concernant les deux parties.", "groups": [{"position": 1, "keywords": ["consigner précisément", "circonstances", "suite de la procédure"]}]}]}]}'::jsonb);

-- secours-appel-malveillant-repete — Troisième engagement de la nuit sur la même adresse, personne n'ouvre
SELECT public.fn_cp_import_case('secours-appel-malveillant-repete', '{"slug": "secours-appel-malveillant-repete", "title": "Troisième engagement de la nuit sur la même adresse, personne n''ouvre", "theme_slug": "police-secours", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 4 heures. C''est la troisième fois cette nuit que vous êtes engagés à la même adresse dans un secteur pavillonnaire, suite à des appels signalant à chaque fois des « cris et bruits de dispute » urgents nécessitant une intervention immédiate. Lors des deux premiers passages, personne n''a répondu malgré des sollicitations répétées, et aucun bruit suspect n''a été constaté depuis l''extérieur.\n\nVotre collègue, épuisé par cette nuit déjà chargée, suggère que cet appel pourrait relever d''un canular ou d''une malveillance visant à mobiliser inutilement les effectifs, une hypothèse plausible compte tenu de la répétition sans jamais aucune confirmation de la réalité des faits signalés.\n\nAucun élément ne permet cependant d''exclure totalement qu''une urgence réelle se cache derrière ces appels répétés, notamment si la situation à l''intérieur avait évolué entre les différents passages.", "questions": [{"position": 1, "max_points": 5, "label": "Comment abordez-vous ce troisième engagement malgré la suspicion croissante de canular ?", "hint": "La probabilité qu''un appel soit malveillant ne dispense jamais de le traiter comme potentiellement réel.", "perfect": "Je traite ce troisième engagement avec le même sérieux que le premier, la suspicion croissante de canular, aussi compréhensible soit-elle après deux passages infructueux, ne devant jamais conduire à négliger la possibilité qu''une urgence réelle se dissimule derrière ces appels répétés.\n\nJe reconnais que la situation a pu évoluer entre les différents passages, une urgence réelle pouvant survenir après un premier appel malveillant ou, à l''inverse, une situation initialement calme pouvant avoir dégénéré depuis notre dernier passage.\n\nJe ne me laisse pas influencer par la fatigue légitime de mon collègue ni par son hypothèse de canular, aussi plausible soit-elle statistiquement, cette lassitude ne devant jamais devenir le facteur déterminant de ma décision d''intervention.\n\nJe procède aux mêmes vérifications rigoureuses que lors des passages précédents, sans les bâcler sous prétexte qu''elles ont déjà été faites deux fois sans résultat.", "points": [{"position": 1, "label": "Traiter ce troisième engagement avec le même sérieux que le premier", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : la suspicion de canular ne dispense jamais de traiter l''appel comme réel.", "groups": [{"position": 1, "keywords": ["même sérieux", "malgré la suspicion", "jamais négliger"]}]}, {"position": 2, "label": "Reconnaître que la situation a pu évoluer entre les passages", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Une urgence réelle peut survenir ou s''aggraver depuis le dernier passage.", "groups": [{"position": 1, "keywords": ["situation a pu évoluer", "urgence réelle possible", "depuis le dernier passage"]}]}, {"position": 3, "label": "Ne pas se laisser influencer par la fatigue ou l''hypothèse du collègue", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "La lassitude ne doit pas devenir le facteur déterminant de la décision.", "groups": [{"position": 1, "keywords": ["ne pas se laisser influencer", "fatigue", "pas facteur déterminant"]}]}, {"position": 4, "label": "Procéder aux mêmes vérifications rigoureuses sans les bâcler", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Ne pas relâcher la rigueur sous prétexte de répétition sans résultat.", "groups": [{"position": 1, "keywords": ["mêmes vérifications", "sans bâcler", "rigueur maintenue"]}]}]}, {"position": 2, "max_points": 5, "label": "Personne ne répond une nouvelle fois. Quelles vérifications complémentaires envisagez-vous au-delà de la simple sonnette et des coups à la porte ?", "hint": "Trois échecs consécutifs de la méthode habituelle appellent une méthode complémentaire, pas un abandon.", "perfect": "Je fais le tour du pavillon si cela est possible, en observant les fenêtres, les éventuelles lumières, ou tout signe d''activité qui n''aurait pas été perceptible depuis la façade principale lors des passages précédents.\n\nJe sollicite si possible des informations auprès des voisins susceptibles de connaître les occupants habituels, ce qui pourrait aider à clarifier si cette adresse correspond à un domicile réellement occupé cette nuit ou à une situation atypique.\n\nJe vérifie auprès du centre d''information et de commandement l''historique complet de ces trois appels, notamment s''ils proviennent du même numéro ou de numéros différents, cette information pouvant orienter mon appréciation de la situation.\n\nJe ne me contente pas de renoncer après ce troisième échec sans avoir exploré ces pistes complémentaires, un abandon prématuré n''étant justifié que si l''ensemble des vérifications raisonnables a été mené sans résultat.", "points": [{"position": 1, "label": "Faire le tour du pavillon pour observer des signes non perceptibles depuis la façade", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Vérification complémentaire au-delà de la sonnette et des coups.", "groups": [{"position": 1, "keywords": ["faire le tour", "signes non perceptibles", "vérification complémentaire"]}]}, {"position": 2, "label": "Solliciter des informations auprès des voisins", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Clarifier si l''adresse correspond à un domicile réellement occupé.", "groups": [{"position": 1, "keywords": ["informations des voisins", "domicile occupé", "clarifier"]}]}, {"position": 3, "label": "Vérifier l''historique complet des appels auprès du centre de commandement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Même numéro ou numéros différents, élément orientant l''appréciation.", "groups": [{"position": 1, "keywords": ["historique des appels", "centre de commandement", "orienter l''appréciation"]}]}, {"position": 4, "label": "Ne pas renoncer prématurément sans avoir exploré ces pistes", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Un abandon n''est justifié qu''après l''ensemble des vérifications raisonnables.", "groups": [{"position": 1, "keywords": ["ne pas renoncer prématurément", "vérifications raisonnables", "avant abandon"]}]}]}, {"position": 3, "max_points": 5, "label": "Après vérification, il s''avère que les trois appels provenaient effectivement d''un numéro masqué différent à chaque fois, confirmant l''hypothèse du canular malveillant. Comment concluez-vous cette série d''interventions ?", "hint": "La confirmation d''un canular après coup ne remet pas en cause la pertinence des interventions menées.", "perfect": "Je ne considère pas ces trois interventions comme du temps perdu ou une réaction disproportionnée, la prudence appliquée à chaque passage ayant été la seule attitude responsable tant que le canular n''était pas confirmé.\n\nJe rends compte avec précision de cette série d''appels malveillants à ma hiérarchie, ce type de comportement pouvant faire l''objet d''une qualification pénale spécifique s''il est possible d''en identifier l''auteur par la suite.\n\nJe consigne l''ensemble des éléments recueillis, notamment l''historique des numéros masqués utilisés, ce qui pourrait être utile si une enquête devait être diligentée pour identifier l''auteur de ces appels malveillants répétés.\n\nJe ne me montre pas découragée par cette conclusion frustrante après une nuit chargée, en gardant à l''esprit que la vigilance appliquée à chaque appel reste la bonne pratique, indépendamment de la nature réelle de chaque signalement révélée après coup.", "points": [{"position": 1, "label": "Ne pas considérer les interventions comme disproportionnées a posteriori", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "La prudence était la seule attitude responsable tant que le canular n''était pas confirmé.", "groups": [{"position": 1, "keywords": ["pas disproportionné", "prudence responsable", "tant que non confirmé"]}]}, {"position": 2, "label": "Rendre compte de cette série d''appels malveillants à la hiérarchie", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Comportement pouvant faire l''objet d''une qualification pénale spécifique.", "groups": [{"position": 1, "keywords": ["rendre compte", "appels malveillants", "qualification pénale"]}]}, {"position": 3, "label": "Consigner les éléments utiles pour une éventuelle enquête d''identification", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Historique des numéros masqués utile pour identifier l''auteur.", "groups": [{"position": 1, "keywords": ["consigner les éléments", "identification de l''auteur", "enquête possible"]}]}, {"position": 4, "label": "Ne pas se décourager, la vigilance reste la bonne pratique", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Indépendamment de la nature révélée après coup de chaque signalement.", "groups": [{"position": 1, "keywords": ["ne pas se décourager", "vigilance bonne pratique", "indépendamment de la nature révélée"]}]}]}]}'::jsonb);

-- secours-victime-refuse-transport-hospitalier — Il saigne mais dit qu'il rentre chez lui à pied
SELECT public.fn_cp_import_case('secours-victime-refuse-transport-hospitalier', '{"slug": "secours-victime-refuse-transport-hospitalier", "title": "Il saigne mais dit qu''il rentre chez lui à pied", "theme_slug": "police-secours", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 23 heures. Vous êtes engagés sur la voie publique pour un homme d''une quarantaine d''années, victime d''une agression ayant entraîné une plaie au niveau du sourcil qui continue de saigner modérément. Les secours médicaux ont été alertés et sont en route, mais l''homme, debout et apparemment lucide, insiste pour « rentrer chez lui à pied » sans attendre leur arrivée ni se rendre à l''hôpital.\n\nIl répète qu''il « a l''habitude », minimisant la gravité apparente de sa blessure malgré le saignement continu, et son discours, bien que globalement cohérent, présente quelques hésitations qui pourraient être liées au choc de l''agression ou à un état plus préoccupant qu''il n''y paraît.\n\nAucune consommation d''alcool ou de substance n''est mentionnée ni détectée à ce stade, et aucun proche n''est présent pour l''accompagner ou apporter un avis complémentaire sur son état habituel.", "questions": [{"position": 1, "max_points": 5, "label": "Le laissez-vous partir sur sa seule affirmation qu''il va bien et qu''il préfère rentrer à pied ?", "hint": "Le respect de l''autonomie d''une personne majeure ne dispense pas d''évaluer sa réelle capacité à décider dans l''instant.", "perfect": "Je ne le laisse pas partir immédiatement sur cette seule affirmation, une plaie qui continue de saigner après une agression pouvant nécessiter des soins que sa propre évaluation, potentiellement affectée par le choc, ne lui permet pas d''apprécier correctement.\n\nJe reste attentive aux hésitations dans son discours, qui pourraient traduire un état de choc ou une conséquence de l''agression plus sérieuse que ce qu''il perçoit lui-même, ce qui justifie une prudence supplémentaire avant d''accepter son refus.\n\nJe ne décide pas seule de la question de sa lucidité et de sa capacité à consentir valablement à un refus de soins, cette évaluation relevant davantage de la compétence des services médicaux déjà en route que de ma seule appréciation policière.\n\nJe l''encourage fermement mais avec bienveillance à attendre l''arrivée des secours déjà sollicités, sans le forcer physiquement, mais en lui expliquant clairement les raisons de cette recommandation.", "points": [{"position": 1, "label": "Ne pas le laisser partir sur sa seule affirmation", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : sa propre évaluation peut être affectée par le choc.", "groups": [{"position": 1, "keywords": ["ne pas laisser partir", "évaluation affectée", "choc possible"]}]}, {"position": 2, "label": "Rester attentive aux hésitations traduisant un état de choc possible", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Conséquence de l''agression plus sérieuse que perçue.", "groups": [{"position": 1, "keywords": ["hésitations dans le discours", "état de choc", "plus sérieux que perçu"]}]}, {"position": 3, "label": "Ne pas décider seul de sa lucidité, laisser cette évaluation aux services médicaux", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Faire évaluer par les secours plutôt que décider seul.", "groups": [{"position": 1, "keywords": ["ne pas décider seul", "évaluation médicale", "services médicaux"]}]}, {"position": 4, "label": "L''encourager fermement mais avec bienveillance à attendre les secours", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sans le forcer physiquement, en expliquant les raisons.", "groups": [{"position": 1, "keywords": ["encourager fermement", "avec bienveillance", "sans forcer"]}]}]}, {"position": 2, "max_points": 5, "label": "Il continue d''insister pour partir en affirmant que c''est son droit. Comment gérez-vous cette insistance jusqu''à l''arrivée des secours ?", "hint": "Son droit réel de refuser des soins existe, mais il s''exerce différemment selon sa capacité effective à consentir à ce moment précis.", "perfect": "Je reconnais qu''il dispose effectivement d''un droit à refuser des soins en tant que personne majeure, sans lui contester ce principe de façon abrupte, ce qui alimenterait inutilement une tension supplémentaire.\n\nJe lui explique cependant clairement que cette évaluation de sa capacité à exercer ce droit dans l''instant, compte tenu de l''agression qu''il vient de subir, revient aux professionnels de santé déjà en route et non à moi-même, ce qui justifie de patienter quelques minutes supplémentaires.\n\nJe ne le retiens pas physiquement contre son gré s''il persiste absolument à vouloir partir avant l''arrivée des secours, une telle contrainte n''étant pas justifiée en l''absence d''éléments plus francs sur son incapacité à décider.\n\nJe consigne avec précision son insistance et les circonstances de cet échange, ce qui pourra être utile pour documenter la situation si un problème devait survenir après son départ éventuel.", "points": [{"position": 1, "label": "Reconnaître son droit à refuser des soins sans le contester abruptement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter une tension supplémentaire inutile.", "groups": [{"position": 1, "keywords": ["reconnaître le droit", "sans contester abruptement", "éviter la tension"]}]}, {"position": 2, "label": "Expliquer que l''évaluation de sa capacité revient aux professionnels de santé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Justifier de patienter le temps de l''arrivée des secours compétents.", "groups": [{"position": 1, "keywords": ["évaluation aux professionnels", "patienter", "secours compétents"]}]}, {"position": 3, "label": "Ne pas le retenir physiquement contre son gré s''il persiste", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Contrainte non justifiée sans éléments plus francs d''incapacité.", "groups": [{"position": 1, "keywords": ["ne pas retenir physiquement", "pas justifié", "sans éléments francs"]}]}, {"position": 4, "label": "Consigner précisément son insistance et l''échange", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Documentation utile en cas de problème après son départ éventuel.", "groups": [{"position": 1, "keywords": ["consigner précisément", "documenter", "problème éventuel"]}]}]}, {"position": 3, "max_points": 5, "label": "Les secours arrivent et, après évaluation, jugent son état suffisamment préoccupant pour insister sur un transport à l''hôpital qu''il refuse encore. Quel est votre rôle à ce stade ?", "hint": "Une fois les professionnels de santé sur place et leur avis rendu, le rôle du policier se recentre différemment.", "perfect": "Je laisse les professionnels de santé mener leur propre évaluation et leur propre dialogue avec lui concernant l''insistance sur le transport, cette question relevant désormais pleinement de leur compétence médicale et non de la mienne.\n\nJe reste disponible pour les appuyer si nécessaire, notamment si une question de sécurité se posait ou si une mesure de contrainte devait être envisagée dans un cadre légal approprié en cas de danger grave et imminent pour lui-même.\n\nJe ne me substitue pas à leur jugement professionnel sur la gravité réelle de son état, en évitant d''exprimer mon propre avis qui pourrait interférer avec leur prise de décision médicale.\n\nJe rends compte avec précision de l''ensemble de cette séquence, y compris de l''avis des secours sur la gravité de son état, ce qui documente complètement cette intervention sensible.", "points": [{"position": 1, "label": "Laisser les professionnels de santé mener leur propre évaluation et dialogue", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Question relevant désormais pleinement de leur compétence médicale.", "groups": [{"position": 1, "keywords": ["laisser les professionnels", "compétence médicale", "leur dialogue"]}]}, {"position": 2, "label": "Rester disponible pour appuyer en cas de nécessité", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Notamment en cas de danger grave et imminent nécessitant une mesure légale.", "groups": [{"position": 1, "keywords": ["rester disponible", "appui si nécessaire", "danger grave et imminent"]}]}, {"position": 3, "label": "Ne pas se substituer à leur jugement professionnel", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter d''interférer avec leur prise de décision médicale.", "groups": [{"position": 1, "keywords": ["ne pas se substituer", "jugement professionnel", "éviter d''interférer"]}]}, {"position": 4, "label": "Rendre compte précisément de toute la séquence", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Documenter complètement cette intervention sensible.", "groups": [{"position": 1, "keywords": ["rendre compte précisément", "documenter", "intervention sensible"]}]}]}]}'::jsonb);

-- secours-differend-chantier-ouvriers — Deux équipes s'affrontent, l'une bloque l'accès des camions
SELECT public.fn_cp_import_case('secours-differend-chantier-ouvriers', '{"slug": "secours-differend-chantier-ouvriers", "title": "Deux équipes s''affrontent, l''une bloque l''accès des camions", "theme_slug": "police-secours", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 10 heures. Vous êtes engagés sur un chantier où deux équipes d''ouvriers, employées par des entreprises sous-traitantes différentes, s''affrontent verbalement avec vigueur suite à un désaccord sur l''ordre d''intervention et un retard de paiement évoqué entre les deux sociétés. L''une des équipes a bloqué physiquement l''accès du chantier avec des palettes, empêchant les camions de l''autre entreprise de livrer du matériel.\n\nLe ton est vif, quelques bousculades ont eu lieu sans blessure, et chaque équipe accuse l''autre de mauvaise foi dans un litige commercial complexe qui semble largement dépasser la compréhension immédiate de la situation par les ouvriers eux-mêmes, pris entre des consignes contradictoires de leur hiérarchie respective.\n\nLes deux contremaîtres présents insistent chacun pour que vous « fassiez évacuer » l''équipe adverse du chantier, chacun étant convaincu d''être dans son bon droit.", "questions": [{"position": 1, "max_points": 5, "label": "Comment qualifiez-vous cette situation et quelle est votre action prioritaire ?", "hint": "Un conflit de travail sous-jacent ne doit pas empêcher de traiter ce qui relève clairement de votre compétence immédiate.", "perfect": "Je qualifie cette situation comme un trouble à l''ordre public résultant d''un litige commercial sous-jacent entre les deux entreprises, ce dernier aspect ne relevant pas de ma compétence à trancher mais le trouble physique constaté, lui, appelant une action immédiate de ma part.\n\nMon action prioritaire est de faire cesser le blocage physique de l''accès par les palettes, ce blocage constituant une entrave concrète et immédiate qui dépasse le simple désaccord verbal entre les deux équipes.\n\nJe sépare les protagonistes les plus véhéments pour faire baisser la tension avant toute autre discussion, sans chercher à comprendre dans le détail les termes du litige commercial qui oppose les deux entreprises entre elles.\n\nJe reste factuelle et neutre envers les deux contremaîtres qui me sollicitent chacun pour faire évacuer l''équipe adverse, en refusant de prendre parti pour l''un ou pour l''autre sur la base de leurs seules affirmations respectives.", "points": [{"position": 1, "label": "Qualifier la situation comme un trouble à l''ordre public distinct du litige commercial", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : distinguer le trouble constaté du fond du litige non arbitrable.", "groups": [{"position": 1, "keywords": ["trouble à l''ordre public", "distinct du litige commercial", "pas à trancher"]}]}, {"position": 2, "label": "Faire cesser le blocage physique de l''accès en priorité", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Entrave concrète qui dépasse le simple désaccord verbal.", "groups": [{"position": 1, "keywords": ["faire cesser le blocage", "entrave concrète", "priorité"]}]}, {"position": 3, "label": "Séparer les protagonistes les plus véhéments pour faire baisser la tension", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Sans chercher à comprendre le détail du litige commercial.", "groups": [{"position": 1, "keywords": ["séparer les protagonistes", "baisser la tension", "sans entrer dans le litige"]}]}, {"position": 4, "label": "Rester neutre envers les deux contremaîtres sans prendre parti", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Refuser de trancher sur la base des seules affirmations respectives.", "groups": [{"position": 1, "keywords": ["rester neutre", "sans prendre parti", "seules affirmations"]}]}]}, {"position": 2, "max_points": 5, "label": "Les deux contremaîtres insistent chacun pour que vous fassiez évacuer l''équipe adverse. Comment répondez-vous à cette double demande contradictoire ?", "hint": "Trancher en faveur de l''un reviendrait à arbitrer un litige qui ne relève pas de votre compétence.", "perfect": "Je refuse de faire évacuer l''une ou l''autre équipe sur la seule base des affirmations contradictoires des deux contremaîtres, une telle décision reviendrait à arbitrer de fait un litige commercial qui ne relève pas de ma compétence.\n\nJe leur explique clairement cette limite de mon intervention, en précisant que mon rôle se limite au rétablissement de l''ordre et à la fin du trouble physique constaté, et non à trancher qui a raison dans leur différend contractuel.\n\nJe les invite tous les deux à faire cesser le blocage volontairement, en expliquant que la poursuite de cette entrave pourrait, elle, être qualifiée pénalement indépendamment de qui a raison sur le fond du litige commercial.\n\nJe les oriente vers les voies appropriées pour régler leur différend commercial, comme une médiation professionnelle ou une action devant la juridiction compétente, ce qui n''est clairement pas le rôle d''une intervention de police sur un chantier.", "points": [{"position": 1, "label": "Refuser de faire évacuer l''une des équipes sur la base des seules affirmations", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Éviter d''arbitrer de fait un litige commercial hors compétence.", "groups": [{"position": 1, "keywords": ["refuser d''évacuer", "arbitrer de fait", "hors compétence"]}]}, {"position": 2, "label": "Expliquer clairement la limite de son rôle aux deux contremaîtres", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Rétablir l''ordre, pas trancher le différend contractuel.", "groups": [{"position": 1, "keywords": ["limite du rôle", "rétablir l''ordre", "pas trancher"]}]}, {"position": 3, "label": "Inviter à faire cesser le blocage volontairement en soulignant le risque pénal", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "L''entrave peut être qualifiée pénalement indépendamment du fond du litige.", "groups": [{"position": 1, "keywords": ["cesser le blocage", "risque pénal", "indépendamment du fond"]}]}, {"position": 4, "label": "Orienter vers les voies appropriées pour le différend commercial", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Médiation professionnelle ou juridiction compétente, hors rôle policier.", "groups": [{"position": 1, "keywords": ["médiation professionnelle", "juridiction compétente", "hors rôle policier"]}]}]}, {"position": 3, "max_points": 5, "label": "Le blocage cesse et les esprits se calment, mais la tension entre les deux équipes reste palpable pour la suite de la journée de travail. Comment clôturez-vous cette intervention ?", "hint": "Le retour au calme immédiat ne garantit pas l''absence de nouvel incident plus tard dans la journée.", "perfect": "Je consigne avec précision les circonstances de ce blocage et son dénouement, ce qui pourrait être utile si un nouvel incident similaire devait survenir plus tard dans la journée sur ce même chantier.\n\nJe recommande aux deux contremaîtres de trouver rapidement une solution avec leur hiérarchie respective sur le litige commercial sous-jacent, cette persistance de la tension pouvant reproduire un incident similaire si rien n''est réglé en amont.\n\nJe ne pars pas sans m''assurer que l''accès du chantier est effectivement dégagé et que les livraisons peuvent reprendre normalement, ce qui constitue le résultat concret attendu de mon intervention.\n\nJe reste joignable pour un éventuel nouvel appel si la tension venait à dégénérer à nouveau dans la journée, sans pour autant rester sur place indéfiniment pour surveiller une situation qui, à ce stade, semble apaisée.", "points": [{"position": 1, "label": "Consigner précisément les circonstances pour un éventuel nouvel incident", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Utile si un incident similaire survenait plus tard dans la journée.", "groups": [{"position": 1, "keywords": ["consigner précisément", "nouvel incident possible", "plus tard dans la journée"]}]}, {"position": 2, "label": "Recommander une résolution rapide du litige commercial sous-jacent", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter la reproduction d''un incident similaire si rien n''est réglé.", "groups": [{"position": 1, "keywords": ["recommander une résolution", "litige sous-jacent", "éviter la reproduction"]}]}, {"position": 3, "label": "S''assurer que l''accès est effectivement dégagé avant de partir", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Résultat concret attendu de l''intervention.", "groups": [{"position": 1, "keywords": ["accès dégagé", "avant de partir", "résultat concret"]}]}, {"position": 4, "label": "Rester joignable sans surveiller indéfiniment une situation apaisée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilité en cas de nouvel appel, sans présence permanente injustifiée.", "groups": [{"position": 1, "keywords": ["rester joignable", "sans surveillance indéfinie", "situation apaisée"]}]}]}]}'::jsonb);

-- secours-personne-coincee-ascenseur — Elle est enfermée depuis quarante minutes et fait une crise d'angoisse
SELECT public.fn_cp_import_case('secours-personne-coincee-ascenseur', '{"slug": "secours-personne-coincee-ascenseur", "title": "Elle est enfermée depuis quarante minutes et fait une crise d''angoisse", "theme_slug": "police-secours", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 20 heures. Vous êtes engagés dans un immeuble de bureaux suite à un appel signalant une femme bloquée dans un ascenseur en panne depuis environ quarante minutes. Le bâtiment est presque vide à cette heure, et la personne, jointe par téléphone via l''interphone de la cabine, commence à manifester des signes de crise d''angoisse, sa respiration s''accélérant et son discours devenant de plus en plus décousu.\n\nLe service technique de maintenance de l''ascenseur a été prévenu mais son délai d''intervention est annoncé à une trentaine de minutes supplémentaires, un temps qui semble long compte tenu de l''état émotionnel croissant de la personne bloquée.\n\nVous ne disposez d''aucun moyen technique pour ouvrir vous-même la cabine ou accélérer sa libération, votre seul contact avec elle se faisant par la voix à travers l''interphone du système de secours.", "questions": [{"position": 1, "max_points": 5, "label": "Face à cette situation où vous ne pouvez techniquement rien faire pour la libérer, quel est votre rôle concret ?", "hint": "L''impuissance technique n''est pas une impuissance totale ; il reste un rôle essentiel à jouer.", "perfect": "Mon rôle concret, en l''absence de toute possibilité technique d''ouvrir moi-même la cabine, est de maintenir un contact vocal rassurant et continu avec elle, ce qui constitue une aide réelle et non négligeable face à sa crise d''angoisse montante.\n\nJe reconnais explicitement les limites de mon intervention technique, sans chercher à forcer ou manipuler un mécanisme que je ne maîtrise pas et qui pourrait aggraver la situation ou compromettre sa sécurité si je m''y risquais maladroitement.\n\nJe coordonne activement avec le service technique pour tenter d''accélérer si possible son intervention, en insistant sur l''état de détresse psychologique croissant de la personne bloquée, ce qui peut influencer la priorisation de leur intervention.\n\nJe reste concentré sur ce qui relève réellement de mon rôle, à savoir l''accompagnement humain de cette attente, plutôt que de me sentir inutile face à l''impossibilité technique de la libérer moi-même.", "points": [{"position": 1, "label": "Maintenir un contact vocal rassurant et continu", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : rassurer et coordonner plutôt que tenter une action technique.", "groups": [{"position": 1, "keywords": ["contact vocal rassurant", "continu", "aide réelle"]}]}, {"position": 2, "label": "Reconnaître les limites de son intervention technique sans forcer le mécanisme", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ne pas aggraver la situation par une manipulation non maîtrisée.", "groups": [{"position": 1, "keywords": ["limites techniques", "ne pas forcer", "ne pas aggraver"]}]}, {"position": 3, "label": "Coordonner activement avec le service technique pour accélérer l''intervention", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Insister sur la détresse psychologique pouvant influencer la priorisation.", "groups": [{"position": 1, "keywords": ["coordonner avec le technique", "accélérer", "détresse psychologique"]}]}, {"position": 4, "label": "Rester concentré sur l''accompagnement humain plutôt que se sentir inutile", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Le rôle d''accompagnement est réel malgré l''impossibilité technique.", "groups": [{"position": 1, "keywords": ["accompagnement humain", "pas inutile", "rôle réel"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment adaptez-vous votre communication face à sa crise d''angoisse montante et son discours de plus en plus décousu ?", "hint": "La manière de parler à une personne en crise d''angoisse diffère de celle utilisée pour informer une personne calme.", "perfect": "Je ralentis mon propre débit de parole et j''adopte un ton particulièrement calme et posé, ce qui peut avoir un effet apaisant contagieux sur son propre rythme respiratoire et sa panique montante.\n\nJe l''aide à se concentrer sur sa respiration en la guidant simplement, comme lui suggérant d''inspirer et d''expirer lentement, ce qui peut l''aider à retrouver un contrôle physiologique sur son état d''angoisse.\n\nJe lui donne des informations concrètes et rassurantes sur ce qui se passe, notamment l''arrivée annoncée du service technique, sans lui cacher le délai réel mais en insistant sur le fait que la situation est prise en charge.\n\nJe ne minimise pas sa détresse en lui disant simplement de « se calmer » de manière abrupte, ce qui serait contre-productif et pourrait renforcer son sentiment de ne pas être comprise dans ce moment difficile.", "points": [{"position": 1, "label": "Ralentir son débit de parole et adopter un ton calme et posé", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Effet apaisant contagieux sur son rythme respiratoire.", "groups": [{"position": 1, "keywords": ["ralentir le débit", "ton calme", "effet apaisant"]}]}, {"position": 2, "label": "L''aider à se concentrer sur sa respiration en la guidant", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Aider à retrouver un contrôle physiologique sur l''angoisse.", "groups": [{"position": 1, "keywords": ["guider la respiration", "contrôle physiologique", "inspirer expirer"]}]}, {"position": 3, "label": "Donner des informations concrètes sans cacher le délai réel", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rassurer sur la prise en charge sans fausse promesse de rapidité.", "groups": [{"position": 1, "keywords": ["informations concrètes", "sans cacher le délai", "situation prise en charge"]}]}, {"position": 4, "label": "Ne pas minimiser sa détresse par un simple « calmez-vous » abrupt", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Contre-productif et renforce le sentiment de ne pas être comprise.", "groups": [{"position": 1, "keywords": ["ne pas minimiser", "pas abrupt", "sentiment d''être comprise"]}]}]}, {"position": 3, "max_points": 5, "label": "Le service technique arrive enfin et libère la personne, en larmes mais physiquement indemne. Comment concluez-vous cette intervention ?", "hint": "La libération physique ne clôt pas nécessairement l''aspect émotionnel de cette épreuve.", "perfect": "Je reste présente un court moment après sa libération pour m''assurer qu''elle reprend ses esprits progressivement, sans la quitter abruptement dès que le problème technique est résolu.\n\nJe reconnais verbalement l''épreuve qu''elle vient de traverser, sans minimiser sa réaction émotionnelle qui reste tout à fait compréhensible après quarante minutes d''enfermement et de crise d''angoisse.\n\nJe m''assure qu''elle est en état de rentrer chez elle ou de reprendre ses activités, en lui proposant si nécessaire de contacter un proche pour l''accompagner si elle semble encore trop affectée pour être seule.\n\nJe remercie le service technique pour son intervention tout en consignant cette intervention avec précision, ce type d''incident restant utile à documenter pour la pratique du service.", "points": [{"position": 1, "label": "Rester présente un court moment après la libération", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ne pas quitter abruptement dès la résolution technique.", "groups": [{"position": 1, "keywords": ["rester présente", "pas abrupt", "après la libération"]}]}, {"position": 2, "label": "Reconnaître verbalement l''épreuve traversée sans minimiser", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Réaction émotionnelle compréhensible après cette épreuve.", "groups": [{"position": 1, "keywords": ["reconnaître l''épreuve", "sans minimiser", "réaction compréhensible"]}]}, {"position": 3, "label": "S''assurer qu''elle est en état de rentrer ou proposer un accompagnement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Contacter un proche si elle semble encore trop affectée.", "groups": [{"position": 1, "keywords": ["état de rentrer", "accompagnement", "contacter un proche"]}]}, {"position": 4, "label": "Remercier le service technique et consigner l''intervention", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Documentation utile pour la pratique future du service.", "groups": [{"position": 1, "keywords": ["remercier le service technique", "consigner", "pratique future"]}]}]}]}'::jsonb);

-- secours-bagarre-sortie-discotheque — Le videur maintient un client au sol depuis plusieurs minutes
SELECT public.fn_cp_import_case('secours-bagarre-sortie-discotheque', '{"slug": "secours-bagarre-sortie-discotheque", "title": "Le videur maintient un client au sol depuis plusieurs minutes", "theme_slug": "police-secours", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 4 h 30. Vous êtes engagés devant une discothèque suite à une bagarre signalée à la sortie de l''établissement. À votre arrivée, un videur maintient plaqué au sol un client visiblement alcoolisé depuis, selon les témoins présents, plusieurs minutes déjà, malgré l''absence apparente de résistance active du client à ce moment précis.\n\nLe client, au sol, gémit et semble avoir des difficultés à respirer normalement compte tenu de la position dans laquelle il est maintenu. Plusieurs autres clients de l''établissement, également alcoolisés à des degrés divers, commentent bruyamment la scène en filmant avec leurs téléphones, certains prenant parti pour l''un ou l''autre protagoniste.\n\nLe videur, en vous voyant arriver, explique que le client « a essayé de frapper un autre videur » quelques minutes plus tôt, ce qui a justifié selon lui cette immobilisation prolongée.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre priorité immédiate face à ce maintien au sol qui semble se prolonger sans nécessité apparente ?", "hint": "Une contrainte privée qui perdure au-delà de ce qui est nécessaire pour neutraliser une menace pose un problème distinct de la question de savoir qui a commencé l''altercation.", "perfect": "Ma priorité immédiate est de faire cesser cette contrainte physique privée qui semble se prolonger au-delà de ce qui paraît nécessaire, l''absence de résistance active du client à cet instant ne justifiant plus, en apparence, un maintien aussi prolongé au sol.\n\nJe m''assure d''abord de l''état respiratoire du client, une position de maintien au sol prolongée pouvant présenter des risques réels pour sa respiration, ce qui constitue une urgence potentielle indépendante de la question des responsabilités dans l''altercation initiale.\n\nJe demande fermement au videur de relâcher sa contrainte dès lors que je constate personnellement l''absence de danger immédiat justifiant sa poursuite, sans pour autant le traiter d''emblée comme l''auteur d''une infraction avant d''avoir recueilli l''ensemble des versions.\n\nJe ne me laisse pas influencer par l''explication donnée par le videur sur les faits antérieurs pour justifier automatiquement la durée de cette contrainte, cette explication devant être vérifiée plutôt qu''acceptée telle quelle dans l''urgence.", "points": [{"position": 1, "label": "Faire cesser la contrainte physique qui semble se prolonger sans nécessité", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : faire cesser la contrainte privée excessive et constater l''état du client.", "groups": [{"position": 1, "keywords": ["faire cesser la contrainte", "prolongée sans nécessité", "priorité immédiate"]}]}, {"position": 2, "label": "S''assurer en priorité de l''état respiratoire du client", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Risque réel pour la respiration lors d''un maintien au sol prolongé.", "groups": [{"position": 1, "keywords": ["état respiratoire", "risque du maintien au sol", "urgence potentielle"]}]}, {"position": 3, "label": "Demander fermement au videur de relâcher sans le traiter d''emblée comme coupable", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vérifier les versions plutôt que conclure immédiatement.", "groups": [{"position": 1, "keywords": ["demander de relâcher", "sans conclure", "vérifier les versions"]}]}, {"position": 4, "label": "Ne pas se laisser influencer par la seule explication du videur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Explication à vérifier plutôt qu''à accepter telle quelle.", "groups": [{"position": 1, "keywords": ["ne pas se laisser influencer", "explication à vérifier", "pas acceptée telle quelle"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment recueillez-vous les différentes versions dans ce contexte de nombreux témoins alcoolisés et en partie filmant la scène ?", "hint": "Les témoignages en milieu festif nocturne présentent des défis particuliers de fiabilité et de gestion collective.", "perfect": "Je recueille séparément la version du client, celle du videur, et si possible celle d''autres témoins moins impliqués émotionnellement, plutôt que de me fier à un récit collectif confus formulé par plusieurs personnes en même temps.\n\nJe tiens compte du fait que l''état d''alcoolisation général de nombreux témoins peut affecter la fiabilité de leurs souvenirs, sans pour autant écarter systématiquement leurs témoignages qui peuvent malgré tout apporter des éléments utiles.\n\nJe ne m''oppose pas à ce que les téléphones filmant la scène continuent d''enregistrer, ces vidéos pouvant au contraire constituer des éléments de preuve objectifs particulièrement utiles pour reconstituer les faits avec précision.\n\nJe reste attentive à gérer l''attroupement grandissant autour de la scène, en demandant si nécessaire à certains badauds de circuler, sans pour autant empêcher les témoins directs de rester disponibles pour la suite de mes vérifications.", "points": [{"position": 1, "label": "Recueillir séparément les versions plutôt qu''un récit collectif confus", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Éviter la contamination mutuelle des témoignages.", "groups": [{"position": 1, "keywords": ["recueillir séparément", "pas de récit collectif", "éviter la contamination"]}]}, {"position": 2, "label": "Tenir compte de l''alcoolisation sans écarter systématiquement les témoignages", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Affecte la fiabilité mais n''invalide pas totalement les éléments apportés.", "groups": [{"position": 1, "keywords": ["alcoolisation", "sans écarter systématiquement", "éléments utiles"]}]}, {"position": 3, "label": "Ne pas s''opposer aux vidéos qui peuvent constituer des preuves utiles", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éléments objectifs pour reconstituer les faits.", "groups": [{"position": 1, "keywords": ["vidéos", "preuves objectives", "reconstituer les faits"]}]}, {"position": 4, "label": "Gérer l''attroupement sans empêcher les témoins directs de rester disponibles", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Distinguer badauds à écarter et témoins utiles à conserver.", "groups": [{"position": 1, "keywords": ["gérer l''attroupement", "témoins directs disponibles", "distinguer les badauds"]}]}]}, {"position": 3, "max_points": 5, "label": "Le client, une fois relâché, présente des difficultés respiratoires persistantes. Comment gérez-vous la suite de cette intervention ?", "hint": "Les conséquences physiques d''une contrainte prolongée peuvent apparaître avec un léger différé.", "perfect": "Je sollicite sans délai une évaluation médicale pour le client, ces difficultés respiratoires persistantes après un maintien au sol prolongé constituant un signe qui ne doit en aucun cas être négligé, même après le relâchement de la contrainte.\n\nJe consigne avec précision la durée approximative du maintien au sol tel que rapporté par les témoins, cette information étant essentielle pour évaluer la proportionnalité de la contrainte exercée par le videur au regard des faits reprochés.\n\nJe recueille les circonstances précises entourant cette contrainte prolongée, ce qui pourra permettre d''apprécier si elle constitue un usage disproportionné de la force par un agent de sécurité privé, indépendamment du comportement initial du client.\n\nJe transmets l''ensemble de ces éléments pour la suite de la procédure, sans préjuger moi-même définitivement de la responsabilité du videur, cette appréciation finale revenant à l''autorité compétente sur la base du dossier complet.", "points": [{"position": 1, "label": "Solliciter sans délai une évaluation médicale pour le client", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Signe à ne pas négliger même après le relâchement de la contrainte.", "groups": [{"position": 1, "keywords": ["évaluation médicale", "sans délai", "signe à ne pas négliger"]}]}, {"position": 2, "label": "Consigner précisément la durée du maintien au sol rapportée par les témoins", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Essentiel pour évaluer la proportionnalité de la contrainte.", "groups": [{"position": 1, "keywords": ["durée du maintien", "proportionnalité", "témoins"]}]}, {"position": 3, "label": "Recueillir les circonstances pour apprécier un éventuel usage disproportionné de la force", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Indépendamment du comportement initial du client.", "groups": [{"position": 1, "keywords": ["circonstances précises", "usage disproportionné", "indépendamment du comportement initial"]}]}, {"position": 4, "label": "Transmettre les éléments sans préjuger de la responsabilité du videur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Appréciation finale revenant à l''autorité compétente.", "groups": [{"position": 1, "keywords": ["transmettre sans préjuger", "autorité compétente", "dossier complet"]}]}]}]}'::jsonb);

-- secours-vehicule-immobilise-voie-rapide — La famille est descendue et marche sur la bande d'arrêt d'urgence
SELECT public.fn_cp_import_case('secours-vehicule-immobilise-voie-rapide', '{"slug": "secours-vehicule-immobilise-voie-rapide", "title": "La famille est descendue et marche sur la bande d''arrêt d''urgence", "theme_slug": "police-secours", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 7 h 30. Vous êtes engagés sur une voie rapide où un véhicule est tombé en panne sur la bande d''arrêt d''urgence. En arrivant, vous constatez que toute la famille, deux adultes et trois enfants en bas âge, est descendue du véhicule et marche à pied le long de la bande d''arrêt d''urgence en direction d''une sortie visible à environ trois cents mètres, exposée directement à la circulation qui continue de rouler à vive allure à quelques mètres d''eux.\n\nLe père explique qu''il pensait « faire au plus vite » en marchant vers la sortie plutôt que d''attendre l''intervention d''une dépanneuse, sans avoir conscience du danger réel que représente cette marche à pied le long d''une voie rapide, particulièrement avec de jeunes enfants.\n\nAucun des membres de la famille ne porte de gilet de sécurité visible, et le véhicule, resté sur la bande d''arrêt d''urgence, n''est pas correctement signalé pour les autres usagers de la voie.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre action absolument prioritaire face à cette famille qui marche exposée à la circulation ?", "hint": "Le danger vient ici directement du comportement des personnes elles-mêmes, pas d''un tiers ou d''un événement extérieur.", "perfect": "Mon action absolument prioritaire est de mettre immédiatement cette famille en sécurité derrière la glissière de sécurité, leur exposition directe à la circulation à vive allure constituant un danger vital immédiat qui prime sur toute autre considération, y compris celle du véhicule en panne.\n\nJe leur fais cesser cette marche à pied sans délai, en les faisant s''arrêter et se mettre à l''abri derrière la glissière plutôt que de continuer vers la sortie, cette progression continuant de les exposer à chaque mètre parcouru.\n\nJe ne perds pas de temps à comprendre en détail leur raisonnement initial avant d''agir sur cette mise en sécurité immédiate, l''urgence de la situation imposant d''abord l''action avant toute explication.\n\nJe reste attentive à la vulnérabilité particulière des jeunes enfants dans ce contexte, leur petite taille les rendant encore moins visibles pour les conducteurs arrivant à vive allure sur cette portion de voie rapide.", "points": [{"position": 1, "label": "Mettre immédiatement la famille en sécurité derrière la glissière", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : mettre les personnes en sécurité derrière la glissière prime sur tout le reste.", "groups": [{"position": 1, "keywords": ["mettre en sécurité", "derrière la glissière", "priorité absolue"]}]}, {"position": 2, "label": "Faire cesser la marche à pied sans délai", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Chaque mètre parcouru continue l''exposition au danger.", "groups": [{"position": 1, "keywords": ["cesser la marche", "sans délai", "exposition continue"]}]}, {"position": 3, "label": "Agir immédiatement sans attendre de comprendre le raisonnement initial", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "L''urgence impose l''action avant l''explication.", "groups": [{"position": 1, "keywords": ["agir immédiatement", "avant l''explication", "urgence prioritaire"]}]}, {"position": 4, "label": "Rester attentive à la vulnérabilité particulière des jeunes enfants", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Moindre visibilité pour les conducteurs à vive allure.", "groups": [{"position": 1, "keywords": ["vulnérabilité des enfants", "moindre visibilité", "vive allure"]}]}]}, {"position": 2, "max_points": 5, "label": "Une fois la famille mise à l''abri, comment gérez-vous le véhicule resté mal signalé sur la bande d''arrêt d''urgence ?", "hint": "Un véhicule mal signalé sur une voie rapide constitue lui-même un danger pour les autres usagers.", "perfect": "Je fais signaler le véhicule de manière visible pour les autres usagers de la voie, ce défaut de signalisation constituant un risque de suraccident supplémentaire pour les véhicules arrivant à vive allure sur cette portion de route.\n\nJe m''assure que personne ne retourne vers le véhicule pour poser cette signalisation sans les précautions de sécurité nécessaires, notamment le port d''un gilet visible si disponible, l''objectif de sécurisation ne devant pas créer un nouveau risque.\n\nJe sollicite l''intervention d''une dépanneuse pour l''évacuation du véhicule dans les meilleurs délais, cette panne prolongée sur la bande d''arrêt d''urgence restant un facteur de risque tant qu''elle n''est pas résolue.\n\nJe reste vigilante sur la circulation environnante pendant toute la durée de cette gestion, en gardant à l''esprit que la vitesse des véhicules sur ce type de voie laisse peu de marge de réaction en cas d''imprévu supplémentaire.", "points": [{"position": 1, "label": "Faire signaler le véhicule de manière visible", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Défaut de signalisation constituant un risque de suraccident.", "groups": [{"position": 1, "keywords": ["signaler le véhicule", "visible", "risque de suraccident"]}]}, {"position": 2, "label": "S''assurer que la pose de signalisation se fasse avec les précautions nécessaires", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ne pas créer un nouveau risque en sécurisant.", "groups": [{"position": 1, "keywords": ["précautions nécessaires", "gilet visible", "pas de nouveau risque"]}]}, {"position": 3, "label": "Solliciter une dépanneuse pour l''évacuation dans les meilleurs délais", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "La panne prolongée reste un facteur de risque tant qu''elle persiste.", "groups": [{"position": 1, "keywords": ["dépanneuse", "évacuation", "meilleurs délais"]}]}, {"position": 4, "label": "Rester vigilante sur la circulation environnante pendant la gestion", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Peu de marge de réaction en cas d''imprévu sur ce type de voie.", "groups": [{"position": 1, "keywords": ["vigilance sur la circulation", "peu de marge", "imprévu supplémentaire"]}]}]}, {"position": 3, "max_points": 5, "label": "Le père, une fois la famille en sécurité, se justifie en expliquant qu''il ne connaissait pas les bons réflexes en cas de panne sur ce type de voie. Comment répondez-vous ?", "hint": "Une explication sincère sur une méconnaissance des règles appelle une réponse pédagogique plutôt qu''un simple reproche.", "perfect": "J''accueille son explication sans excès de reproche, en comprenant que son geste, bien que dangereux, partait d''une intention compréhensible de vouloir mettre rapidement sa famille en sécurité en cherchant à atteindre la sortie la plus proche.\n\nJe lui explique clairement les bons réflexes à adopter en cas de panne sur ce type de voie, notamment rester dans le véhicule ou en sécurité derrière la glissière plutôt que de marcher le long de la circulation, ce qui constitue une information utile pour l''avenir.\n\nJe ne minimise pas pour autant la gravité du danger qu''il a fait courir à sa famille par méconnaissance, en restant clair sur le fait que cette explication, bien que compréhensible, ne rend pas le geste moins dangereux qu''il ne l''était réellement.\n\nJe consigne cet incident avec précision, ce type de méconnaissance des bons réflexes étant malheureusement fréquent et pouvant utilement alimenter une réflexion sur la pédagogie à développer sur ce sujet.", "points": [{"position": 1, "label": "Accueillir l''explication sans excès de reproche", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Intention compréhensible de vouloir mettre rapidement la famille en sécurité.", "groups": [{"position": 1, "keywords": ["sans excès de reproche", "intention compréhensible", "accueillir l''explication"]}]}, {"position": 2, "label": "Expliquer clairement les bons réflexes pour l''avenir", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Rester dans le véhicule ou derrière la glissière plutôt que marcher.", "groups": [{"position": 1, "keywords": ["bons réflexes", "rester dans le véhicule", "pour l''avenir"]}]}, {"position": 3, "label": "Ne pas minimiser la gravité du danger malgré la méconnaissance", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "L''explication ne rend pas le geste moins dangereux qu''il ne l''était.", "groups": [{"position": 1, "keywords": ["ne pas minimiser", "gravité du danger", "malgré la méconnaissance"]}]}, {"position": 4, "label": "Consigner l''incident pour alimenter une réflexion pédagogique", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Méconnaissance fréquente pouvant justifier une pédagogie développée.", "groups": [{"position": 1, "keywords": ["consigner", "réflexion pédagogique", "méconnaissance fréquente"]}]}]}]}'::jsonb);

